.miniroom-candle::before { content: ''; position: absolute; top: -7px; left: -1px; width: 4px; height: 6px; border-radius: 60% 60% 45% 45%; background: #eeae59; }
[data-theme='birthday'] .miniroom-cake { display: block; }
.miniroom-ticket { display: none; position: absolute; right: 9%; top: 52px; padding: 6px 8px; color: #74603e; background: #f4dfa8; border: 2px dashed #c6b37e; font-size: 8px; letter-spacing: 1px; font-weight: 700; transform: rotate(8deg); }
[data-theme='festival'] .miniroom-ticket { display: block; }
[data-theme='festival'][data-time='night'] .miniroom-bunting { filter: drop-shadow(0 0 4px #ffed9c); }
.miniroom-tv { display: none; position: absolute; top: 44px; right: 14%; width: 70px; height: 48px; padding: 5px; background: #bda6ca; border: 3px solid #987ba6; border-radius: 7px; transform: rotate(3deg); box-shadow: 3px 4px 0 #64745020; }
.miniroom-tv span { display: grid; place-items: center; height: 100%; background: #e9f0df; border: 2px solid #886e94; color: #9ead89; font-size: 14px; }
.miniroom-tv i { position: absolute; bottom: -8px; left: 20px; height: 6px; width: 26px; border-bottom: 2px solid #987ba6; }
[data-theme='broadcast'] .miniroom-tv { display: block; }
.miniroom-record { display: none; position: absolute; top: 44px; right: 16%; width: 46px; height: 46px; background: #4c5750; border: 4px solid #6c786f; border-radius: 50%; box-shadow: 3px 3px 0 #90977c20, inset 0 0 0 3px #7c8475; }
.miniroom-record i { position: absolute; inset: 12px; border: 2px solid #d4b4bc; border-radius: 50%; background: #eccebf; }
.miniroom-music-note { position: absolute; font-family: monospace; font-size: 25px; color: #a786b2; top: -17px; left: -32px; transform: rotate(-10deg); }
.miniroom-music-note:last-child { left: 52px; top: -3px; color: #73956a; transform: rotate(10deg); }
[data-theme='release'] .miniroom-record { display: block; }
.miniroom-season-leaf { position: absolute; top: 26px; left: 20%; width: 9px; height: 13px; border-radius: 8px 0 8px 0; transform: rotate(35deg); background: #bfaa71; opacity: .65; }
.miniroom-season-leaf-b { left: auto; right: 27%; top: 18px; transform: rotate(135deg); background: #c68873; }
[data-season='spring'] .miniroom-season-leaf { border-radius: 60% 40%; background: #e9b7c1; }
[data-season='summer'] .miniroom-season-leaf { background: #9fbf82; }
[data-season='winter'] .miniroom-season-leaf { border-radius: 50%; background: #fffdf0; border: 1px solid #ced9e2; width: 7px; height: 7px; opacity: .9; }
@media (max-width: 760px) {
  .miniroom-scene { height: 265px; }
  .miniroom-heading { align-items: start; gap: 10px; padding: 15px 16px 12px; }
  .miniroom-heading h2 { font-size: 16px; }
  .miniroom-clock { font-size: 9px; }
  .miniroom-cast { width: calc(100% - 24px); }
  .miniroom-photo { width: 86px; }
  .miniroom-member-hint { margin-inline: 16px; }
  .miniroom-caption { padding-inline: 16px; }
  .miniroom-conversation { margin-inline: 16px; }
  .miniroom-credit { margin-inline: 16px; }
}
@media (max-width: 480px) {
  .miniroom-heading { flex-wrap: wrap; gap: 8px; }
  .miniroom-heading > div { width: 100%; }
  .miniroom-clock { padding: 3px 7px; }
  .miniroom-scene { height: 245px; background-position: center 55%; }
  .miniroom-cast { gap: 0; bottom: 20px; width: calc(100% - 18px); }
  .miniroom-photo { width: 66px; }
  .miniroom-character::after { width: 32px; height: 7px; }
  .miniroom-member-name { font-size: 10px; padding-inline: 6px; }
  .miniroom-conversation { gap: 7px; padding: 10px; align-items: start; }
  .miniroom-member-intro { font-size: 11px; }
  .miniroom-video-button { padding: 6px 8px; font-size: 10px; }
  .miniroom-caption { font-size: 10px; }
  .miniroom-credit { font-size: 9px; }
  .miniroom-bunting { width: 52%; left: 24%; }
  .miniroom-bunting i { border-inline-width: 6px; border-top-width: 12px; }
  .miniroom-balloon-a { left: 9%; }
  .miniroom-balloon-b { right: 9%; }
  .miniroom-cake { right: 23%; top: 53px; transform: scale(.85); }
  .miniroom-tv { right: 11%; top: 44px; transform: scale(.85) rotate(3deg); }
  .miniroom-ticket { right: 9%; font-size: 7px; padding: 5px; }
  .miniroom-record { transform: scale(.85); }
}
@media (prefers-reduced-motion: reduce) { .miniroom-scene::before { transition: none; } }
